commit 8ff8bb328f5d4c2981933ff7847374ddc747d572
Author: James Bonfield <jkb@sanger.ac.uk>
Date:   Mon Mar 9 11:45:22 2020 +0000

    Improved CRAM error messages in cram_decode_slice (PR #1042)

    To help diagnose #1038 (Embedded reference issues) by reporting
    which ref_id and region is affected.

diff --git a/cram/cram_decode.c b/cram/cram_decode.c
index 8cf3403b..c7eb6606 100644
--- a/cram/cram_decode.c
+++ b/cram/cram_decode.c
@@ -2198,7 +2198,9 @@ int cram_decode_slice(cram_fd *fd, cram_container *c, cram_slice *s,
         if (embed_ref) {
             cram_block *b;
             if (s->hdr->ref_base_id < 0) {
-                hts_log_error("No reference specified and no embedded reference is available");
+                hts_log_error("No reference specified and no embedded reference is available"
+                              " at #%d:%"PRId64"-%"PRId64, ref_id, s->hdr->ref_seq_start,
+                              s->hdr->ref_seq_start + s->hdr->ref_seq_span-1);
                 return -1;
             }
             b = cram_get_block_by_id(s, s->hdr->ref_base_id);
@@ -2210,7 +2212,8 @@ int cram_decode_slice(cram_fd *fd, cram_container *c, cram_slice *s,
             s->ref_start = s->hdr->ref_seq_start;
             s->ref_end   = s->hdr->ref_seq_start + s->hdr->ref_seq_span-1;
             if (s->ref_end - s->ref_start > b->uncomp_size) {
-                hts_log_error("Embedded reference is too small");
+                hts_log_error("Embedded reference is too small at #%d:%d-%d",
+                              ref_id, s->ref_start, s->ref_end);
                 return -1;
             }
         } else if (!c->comp_hdr->no_ref) {
@@ -2229,7 +2232,9 @@ int cram_decode_slice(cram_fd *fd, cram_container *c, cram_slice *s,

             /* Sanity check */
             if (s->ref_start < 0) {
-                hts_log_warning("Slice starts before base 1");
+                hts_log_warning("Slice starts before base 1"
+                                " at #%d:%"PRId64"-%"PRId64, ref_id, s->hdr->ref_seq_start,
+                                s->hdr->ref_seq_start + s->hdr->ref_seq_span-1);
                 s->ref_start = 0;
             }
             pthread_mutex_lock(&fd->ref_lock);
@@ -2246,8 +2251,8 @@ int cram_decode_slice(cram_fd *fd, cram_container *c, cram_slice *s,

     if ((fd->required_fields & SAM_SEQ) &&
         s->ref == NULL && s->hdr->ref_seq_id >= 0 && !c->comp_hdr->no_ref) {
-        hts_log_error("Unable to fetch reference #%d %"PRId64"..%"PRId64"\n",
-                      s->hdr->ref_seq_id, s->hdr->ref_seq_start,
+        hts_log_error("Unable to fetch reference #%d:%"PRId64"-%"PRId64"\n",
+                      ref_id, s->hdr->ref_seq_start,
                       s->hdr->ref_seq_start + s->hdr->ref_seq_span-1);
         return -1;
     }
@@ -2266,14 +2271,16 @@ int cram_decode_slice(cram_fd *fd, cram_container *c, cram_slice *s,
             if (s->hdr->ref_seq_start >= s->ref_start) {
                 start = s->hdr->ref_seq_start - s->ref_start;
             } else {
